const body = $('ENVIAR MENSAGEM').first().json.body;
const conexao = $('DADOS CONEXAO TEXTO').first().json;

if (!conexao?.access_token || !conexao?.phone_number_id) {
  throw new Error('Conexao nao encontrada ou sem dados da API Oficial.');
}

const to = String(body.telefone || '').replace(/\D/g, '');
if (!to) throw new Error('Campo telefone obrigatorio.');

const payload = {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to,
  type: 'text',
  text: { body: body.mensagem }
};

if (body.mensagemRespondida) {
  payload.context = { message_id: body.mensagemRespondida };
}

const metaRes = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://graph.facebook.com/v21.0/${conexao.phone_number_id}/messages`,
  headers: {
    Authorization: `Bearer ${conexao.access_token}`,
    'Content-Type': 'application/json'
  },
  body: payload,
  json: true
});

if (metaRes.error) {
  throw new Error(metaRes.error.message || metaRes.error.error_user_msg || 'Falha ao enviar mensagem na Meta.');
}

const metaMessageId = metaRes.messages?.[0]?.id || null;
if (!metaMessageId) {
  throw new Error('Meta nao retornou message id.');
}

return [
  {
    json: {
      idMensagem: body.idMensagem,
      metaMessageId,
      metaStatus: 'sent'
    }
  }
];

const body = $('ENVIAR MIDIA').first().json.body;
const conexao = $('DADOS CONEXAO MIDIA').first().json;
const link = $('LINK ARQUIVO1').first().json.link;

if (!conexao?.access_token || !conexao?.phone_number_id) {
  throw new Error('Conexao nao encontrada ou sem dados da API Oficial.');
}

const to = String(body.telefone || '').replace(/\D/g, '');
if (!to) throw new Error('Campo telefone obrigatorio.');

const apiVersion = 'v21.0';
const baseUrl = `https://graph.facebook.com/${apiVersion}/${conexao.phone_number_id}/messages`;
const headers = {
  Authorization: `Bearer ${conexao.access_token}`,
  'Content-Type': 'application/json'
};

const typeMap = {
  audioMessage: 'audio',
  imageMessage: 'image',
  videoMessage: 'video',
  documentMessage: 'document',
  stickerMessage: 'sticker'
};

const metaType = typeMap[body.type];
if (!metaType) {
  throw new Error(`Tipo de midia nao suportado na API Oficial: ${body.type}`);
}

async function sendMeta(payload) {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: baseUrl,
    headers,
    body: payload,
    json: true
  });

  if (res.error) {
    throw new Error(res.error.message || res.error.error_user_msg || 'Falha ao enviar midia na Meta.');
  }

  return res.messages?.[0]?.id || null;
}

let captionMetaId = null;

if (body.type === 'audioMessage' && body.caption) {
  captionMetaId = await sendMeta.call(this, {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to,
    type: 'text',
    text: { body: body.caption }
  });
}

const mediaBlock = { link };

if (body.caption && body.type !== 'audioMessage') {
  mediaBlock.caption = body.caption;
}

if (body.type === 'documentMessage') {
  const fileName = String(link || '').split('?')[0].split('/').pop() || 'arquivo';
  mediaBlock.filename = decodeURIComponent(fileName);
}

const mediaMetaId = await sendMeta.call(this, {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to,
  type: metaType,
  [metaType]: mediaBlock
});

if (!mediaMetaId) {
  throw new Error('Meta nao retornou message id da midia.');
}

return [
  {
    json: {
      idMensagem: body.idMensagem,
      idMensagem2: body.idMensagem2 || null,
      tipoMensagem: body.type,
      link,
      captionMetaId,
      mediaMetaId,
      metaStatus: 'sent'
    }
  }
];

